import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    T = int(input[ptr])
    ptr += 1
    for _ in range(T):
        N = int(input[ptr])
        ptr += 1
        A = list(map(int, input[ptr:ptr+N]))
        ptr += N

        freq = defaultdict(int)
        for num in A:
            freq[num] += 1

        max_dist = 0
        B = [0] * N
        pos = 0
        for num in A:
            if freq[num] == 2:
                if pos < N - 1 and A[pos+1] != num:
                    B[pos] = A[pos+1]
                    B[pos+1] = num
                    pos += 2
                    max_dist += 2
                else:
                    B[pos] = num
                    pos += 1
            else:
                B[pos] = num
                pos += 1
                max_dist += 1

        if max_dist < N:
            for i in range(N):
                if B[i] == A[i]:
                    for j in range(i+1, N):
                        if B[j] != A[j] and B[j] != A[i]:
                            B[i], B[j] = B[j], B[i]
                            max_dist += 1
                            break

        print(max_dist)
        print(' '.join(map(str, B)))

solve()
